@startuml

class Employee {
  + Name
  + Ssn
}

class CreativeEmployee extends Employee {
  + HasOscar : boolean
}

class Director extends CreativeEmployee {
  + AssistantName
}

class Actor extends CreativeEmployee {
  + Education
}

class Technician extends Employee {
  + FieldOfActivity
}

class FilmSet {
  + Location
}

class Film {
  + Title
  + ReleaseYear
}

class Genre {
  + Type
}

class Screenwriter {
  + Name
  + MostSuccessfulFilm
}

class Screenplay {
  + Title
  + Version
  + Date
  + NumberOfScenes
  + Plot
}

class Novel {
  + Title
  + Author
}

class Concept {
}

FilmSet "*" -- "*" Film

Film "*" -- "1" Genre
Film "1" -- "1" Screenplay
Film "*" -- "1" Screenplay : based on

Screenplay "*" -- "1" Screenwriter
Screenplay "0..1" -- "0..1" Novel
Screenplay "0..1" -- "0..1" Concept

Actor "*" -- "1" Screenplay : reads

@enduml

